$ErrorActionPreference='Stop'
function Decode([byte[]]$s,[int]$n){$d=[byte[]]::new($n);$ip=0;$op=0;while($ip-lt$s.Length){$t=$s[$ip++];$l=$t-shr4;if($l-eq15){do{$x=$s[$ip++];$l+=$x}while($x-eq255)};[Array]::Copy($s,$ip,$d,$op,$l);$ip+=$l;$op+=$l;if($ip-eq$s.Length){break};$o=[int]$s[$ip]+256*[int]$s[$ip+1];$ip+=2;$l=($t-band15)+4;if(($t-band15)-eq15){do{$x=$s[$ip++];$l+=$x}while($x-eq255)};for($j=0;$j-lt$l;$j++){$d[$op]=$d[$op-$o];$op++}};if($op-ne$n){throw 'size'};return ,$d}
function Packed{$n=$r.ReadInt64();if($n-lt0-or$n-gt10000000){throw "size $n at $($st.Position)"};$m=[IO.MemoryStream]::new();while($m.Length-lt$n){$c=$r.ReadInt32();$p=$r.ReadInt32();$d=Decode ($r.ReadBytes($p)) $c;$m.Write($d)};return ,$m.ToArray()}
function Text{$n=$r.ReadInt32();if($n-eq0){return ''};return [Text.Encoding]::UTF8.GetString((Packed))}
function Values($n){$d=Packed;if($d.Length-ne$n*8){throw 'size'};return ,@(for($j=0;$j-lt$n;$j++){[BitConverter]::ToDouble($d,$j*8)})}
$inv=Get-Content -Raw validation/rechecks/2026-10-31/binary-zemax-bsdf/installed-speos-inventory.json|ConvertFrom-Json
$paths=@($inv|Where-Object {$_.Header-match'v11.*\n1'}|Select-Object -First 3 -ExpandProperty Path)+@((Resolve-Path 'validation/rechecks/2026-10-31/speos-v11-xyz/official-texture.anisotropicbsdf').Path)
foreach($p in $paths){$b=[IO.File]::ReadAllBytes($p);$st=[IO.MemoryStream]::new($b);$r=[IO.BinaryReader]::new($st);$header=[Text.Encoding]::ASCII.GetString($b,0,[Array]::IndexOf($b,[byte]10));$v=if($header-match'v11'){11}else{9};$st.Position=[Array]::IndexOf($b,[byte]10)+11+([int]($v-eq11));"FILE $p HEADER $header";try{Text;Text;$st.Position+=24;"R $($r.ReadByte()) T $($r.ReadByte()) N1 $($r.ReadDouble()) N2 $($r.ReadDouble()) Q $($r.ReadByte()) E $($r.ReadByte())";"POS $($st.Position) HEX $([BitConverter]::ToString($b,[int]$st.Position,48))";if($v-eq11){"extra $($r.ReadDouble())"};$nr=$r.ReadInt32();"nr $nr rot $((Values $nr)-join',')";$ni=$r.ReadInt32();"ni $ni inc $((Values $ni)-join',')"}catch{$_}}
